package com.repairconnect.controller;
import com.repairconnect.entity.*; import com.repairconnect.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/providers/services") public class ServiceController {final ProviderRepository providers;final ServiceRepository services;final ServiceCategoryRepository categories; ServiceController(ProviderRepository p,ServiceRepository s,ServiceCategoryRepository c){providers=p;services=s;categories=c;} record Request(Long categoryId,String serviceName,String description,Double price,Integer estimatedDuration){} @GetMapping @PreAuthorize("hasRole('SERVICE_PROVIDER')") List<ServiceItem> myServices(org.springframework.security.core.Authentication a){var p=providers.findByUserEmail(a.getName()).orElseThrow();return services.findByProviderId(p.getId());} @PostMapping @PreAuthorize("hasRole('SERVICE_PROVIDER')") ServiceItem add(@RequestBody Request r,org.springframework.security.core.Authentication a){var p=providers.findByUserEmail(a.getName()).orElseThrow();return services.save(new ServiceItem(p,categories.findById(r.categoryId()).orElseThrow(),r.serviceName(),r.price()));} @DeleteMapping("/{id}") @PreAuthorize("hasRole('SERVICE_PROVIDER')") void remove(@PathVariable Long id,org.springframework.security.core.Authentication a){var s=services.findById(id).orElseThrow();if(!s.getProvider().getUser().getEmail().equals(a.getName()))throw new RuntimeException("Not your service");services.delete(s);} }